      index,
      name: item.name,
      status: item.status,
      query: item.query,
      product,
      option: sel.option,
      optionCount: opts.length,
      packages: sel.packages,
      cost,
      removed,
      missing,
      flags: product?.flags ?? [],
    };
  });

