  const agent = fakeAgent({ outcome: (u) => (u === url(0) ? "out_of_stock" : "added") });
  const rev = review(2, [line(5, { packages: 2, product: { name: "Bok Choy (~1.5lb)", url: url(5), perLb: true } })]);
