import { createAgentClient } from "./server/cart/agent.js";
import { planCartRun, runCartBuild } from "./server/cart/buildCart.js";
const agent = createAgentClient({ apiKey: process.env.TINYFISH_API_KEY });
const L = (index, name, query, productName, url) => ({ index, name, query, removed: false, missing: false, packages: 1, cost: 1, product: { name: productName, url } });
const review = { lines: [
  L(0, "garlic", "garlic", "Garlic 3pcs", "https://www.tntsupermarket.com/eng/05008501-garlic.html"),
  L(1, "green onions", "green onion", "Green Onion (1bunch)", "https://www.tntsupermarket.com/eng/05014501-green-onion.html"),
]};
const run = planCartRun(review, { sub: "live-test", approvedAt: new Date().toISOString(), total: 2, itemCount: 2 });
const ctl = new AbortController(); const t = Date.now();
const done = runCartBuild(run, { agent, profileId: process.env.TINYFISH_PROFILE_ID, signal: ctl.signal, pollMs: 3000,
  save: (c) => { const r = c.runs[0]; if (r?.status === "RUNNING" && !ctl.signal.aborted) { console.log(`[${((Date.now()-t)/1000).toFixed(0)}s] running ${r.runId}; cancelling`); ctl.abort(); } } });
