input.command:
node --env-file=.env.local --input-type=module -e '
import { createAgentClient } from "./server/cart/agent.js";
import { planCartRun, runCartBuild } from "./server/cart/buildCart.js";
const B = "https://www.tntsupermarket.com/eng/";
const L = (index, name, query, productName, slug, size = null) => ({ index, name, query, removed: false, missing: false, packages: 1, cost: 1, product: { name: productName, url: B + slug, perLb: Boolean(size), size } });
const review = { lines: [
  L(0, "ground pork", "ground pork", "Ground Pork - Regular (~2lb)", "03011701-ground-pork-regular.html", { amount: 907, unit: "g", approx: true }),
  L(1, "green onions", "green onion", "Green Onion (1bunch)", "05014501-green-onion.html"),
  L(2, "chicken thighs", "chicken thigh", "Fresh Chicken Thigh Boneless Skinless Value Pack (2.5lb)", "03030001-fresh-chicken-thigh-boneless-skinless-value-pack.html", { amount: 1134, unit: "g", approx: false }),
  L(3, "firm tofu", "firm tofu", "Superior Natural Firm Tofu (454g)", "51280001-superior-firm-tofu.html"),
]};
const run = planCartRun(review, { sub: "live-test", approvedAt: new Date().toISOString(), total: 4, itemCount: 4 });
console.log("targets:", run.items.map(i => `${i.name}=${i.targetLb ?? i.packages}`).join(", "));
const t = Date.now(); let last = "";
await runCartBuild(run, { agent: createAgentClient({ apiKey: process.env.TINYFISH_API_KEY }), profileId: process.env.TINYFISH_PROFILE_ID, pollMs: 5000,
  save: (c) => { const s = c.runs.map(r => `#${r.batch}a${r.attempt}:${r.status}/${r.steps ?? "-"}`).join(" "); if (s !== last) { last = s; console.log(`[${((Date.now()-t)/1000).toFixed(0)}s]`, s, c.runs.map(r => r.lastAction ? "«"+r.lastAction.slice(0,50)+"»" : "").join(" ")); } } });
console.log(JSON.stringify({ wall: ((Date.now()-t)/1000).toFixed(0)+"s", concurrency: run.concurrency, status: run.status, steps: run.steps, items: run.items.map(i => [i.name, i.outcome, i.quantityInCart, (i.note ?? "").slice(0, 90)]) }, null, 1));
'

