S=/private/tmp/claude-501/-Users-mglean-HackWestern/942be125-d035-4c37-9952-22ef3cc914ed/scratchpad/spike && cat > $S/explore.mjs <<'EOF'
import { chromium } from "playwright-core";
const key = process.env.TINYFISH_API_KEY;
const t0 = Date.now(); const ts = () => ((Date.now() - t0) / 1000).toFixed(1) + "s";
const res = await fetch("https://api.browser.tinyfish.ai", {
  method: "POST", headers: { "X-API-Key": key, "Content-Type": "application/json" },
  body: JSON.stringify({ url: "https://www.tntsupermarket.com/eng/", timeout_seconds: 180, proxy_config: { country_code: "CA" } }),
  signal: AbortSignal.timeout(90_000),
});
const s = await res.json().catch(() => null);
console.log(ts(), "create:", res.status, s?.error?.code ?? "", s?.session_id ?? "");
if (!res.ok) process.exit(1);
try {
  const browser = await chromium.connectOverCDP(s.cdp_url, { timeout: 60_000 });
  const page = browser.contexts()[0].pages()[0] ?? await browser.contexts()[0].newPage();
  await page.waitForLoadState("domcontentloaded", { timeout: 60_000 }).catch(() => {});
  await page.waitForTimeout(6000);
  console.log(ts(), "url:", page.url(), "| title:", await page.title());
  const body = await page.evaluate(() => document.body.innerText.slice(0, 600));
  console.log("BODY:", JSON.stringify(body));
  const cands = await page.evaluate(() => [...document.querySelectorAll("button, a, [role=button], div, span")]
    .filter(e => /L\dT|N\dG|postal|Delivery|Pickup/i.test(e.textContent ?? "") && (e.textContent ?? "").length < 60 && e.children.length <= 3)
    .slice(0, 15).map(e => `${e.tagName}.${(e.className && typeof e.className === "string") ? e.className.split(" ").slice(0,2).join(".") : ""} [${e.getAttribute("aria-label") ?? ""}] "${e.textContent.trim().replace(/\s+/g, " ")}"`));
  console.log("CANDIDATES:\n " + cands.join("\n "));
  await page.screenshot({ path: process.argv[2] + "/home.png" });
} finally {
  const d = await fetch(`https://api.browser.tinyfish.ai/${s.session_id}`, { method: "DELETE", headers: { "X-API-Key": key } });
  console.log(ts(), "deleted:", d.status);
}
EOF
cd /Users/mglean/HackWestern && NODE_PATH=$S/node_modules node --env-file=.env.local -e "import('$S/explore.mjs')" -- $S 2>&1 | tail -30

