const SEARCH = "https://www.tntsupermarket.com/eng/search.html?query=large%20eggs";
const P = "M2_VENIA_BROWSER_PERSISTENCE__";
const res = await fetch("https://api.browser.tinyfish.ai", { method: "POST", headers: { "X-API-Key": key, "Content-Type": "application/json" },
  body: JSON.stringify({ url: SEARCH, timeout_seconds: 240, proxy_config: { country_code: "CA" } }) });
const s = await res.json();
const eggs = async (page) => {
  await page.waitForFunction(() => /\$\d/.test(document.body.innerText) || /couldn.t find/.test(document.body.innerText), null, { timeout: 30_000 }).catch(() => {});
  await page.waitForTimeout(1500);
  return [...new Set(await page.evaluate(() => [...document.querySelectorAll("a[href*='/eng/'][href$='.html']")].map(a => a.textContent.trim()).filter(t => /egg/i.test(t))))];
};
const state = (page) => page.evaluate((P) => ({
  postcode: localStorage.getItem(P + "x-postcode"), store: localStorage.getItem(P + "x-prefered-store-code"),
  header: document.querySelector("[class*='deliverCss-city']")?.textContent }), P);
try {
  const browser = await chromium.connectOverCDP(s.cdp_url, { timeout: 60_000 });
  const page = browser.contexts()[0].pages()[0];
  const gql = [];
  page.on("request", (r) => { if (/graphql/.test(r.url()) && /store|post|pickup|address|source/i.test(decodeURIComponent(r.url()) + (r.postData() ?? ""))) gql.push(decodeURIComponent(r.url()).replace(/^.*graphql\?query=/, "").slice(0, 150) + (r.postData() ? " BODY:" + r.postData().slice(0, 200) : "")); });
  await page.waitForLoadState("domcontentloaded").catch(() => {});
  const before = await eggs(page);
  console.log(ts(), "BEFORE", JSON.stringify(await state(page)), "| eggs:", before.length, "| 12pc Burnbrae Large:", before.includes("Burnbrae Farms Large Eggs (12pcs)"));

  await page.evaluate((P) => {
    const now = Date.now();
    localStorage.setItem(P + "x-postcode", JSON.stringify({ value: JSON.stringify("N6G"), timeStored: now }));
    localStorage.removeItem(P + "x-prefered-store-code");
  }, P);
  gql.length = 0;
  await page.goto(SEARCH, { waitUntil: "domcontentloaded" });
  const after = await eggs(page);
  console.log(ts(), "AFTER ", JSON.stringify(await state(page)), "| eggs:", after.length, "| 12pc Burnbrae Large:", after.includes("Burnbrae Farms Large Eggs (12pcs)"));
  console.log("only at L3T:", before.filter((n) => !after.includes(n)));
  console.log("only at N6G:", after.filter((n) => !before.includes(n)));
  console.log("store-related GraphQL after switch:\n " + [...new Set(gql)].slice(0, 10).join("\n "));
  console.log("access denied?", await page.evaluate(() => /Access Denied/i.test(document.body.innerText)));
} catch (e) { console.log("ERROR", e.message.split("\n")[0]); }
finally {
  const d = await fetch(`https://api.browser.tinyfish.ai/${s.session_id}`, { method: "DELETE", headers: { "X-API-Key": key } });
  console.log(ts(), "deleted:", d.status);
}
EOF
