  const browser = await chromium.connectOverCDP(s.cdp_url, { timeout: 60_000 });
  const page = browser.contexts()[0].pages()[0];
  await page.waitForLoadState("domcontentloaded").catch(() => {});
  await page.waitForTimeout(5000);
  // Search the site's own JS for the query that maps a postcode to stores.
  const hits = await page.evaluate(async () => {
    const urls = [...new Set(performance.getEntriesByType("resource").map((e) => e.name).filter((u) => /\.js(\?|$)/.test(u) && u.includes("tntsupermarket.com")))];
    const out = [];
    for (const u of urls) {
      const txt = await fetch(u).then((r) => r.text()).catch(() => "");
      for (const re of [/query\s+\w*(?:[Pp]ickup|[Ss]tore[A-Z]\w*|[Ss]ource|[Pp]ostcode|[Pp]ostal)\w*[^`]{0,400}/g, /prefered-store-code[^;]{0,200}/g]) {
        for (const m of txt.matchAll(re)) out.push(u.split("/").pop().slice(0, 30) + " :: " + m[0].replace(/\s+/g, " ").slice(0, 300));
      }
    }
    return { scripts: urls.length, hits: [...new Set(out)].slice(0, 30) };
  });
  console.log("scripts scanned:", hits.scripts);
  for (const h of hits.hits) console.log("-", h);
} catch (e) { console.log("ERROR", e.message.split("\n")[0]); }
finally {
  await fetch(`https://api.browser.tinyfish.ai/${s.session_id}`, { method: "DELETE", headers: { "X-API-Key": key } });
}
EOF
