import { chromium } from "playwright-core";
const key = process.env.TINYFISH_API_KEY;
const res = await fetch("https://api.browser.tinyfish.ai", { method: "POST", headers: { "X-API-Key": key, "Content-Type": "application/json" },
  body: JSON.stringify({ url: "https://www.tntsupermarket.com/eng/", timeout_seconds: 180, proxy_config: { country_code: "CA" } }) });
const s = await res.json();
