      const txt = await fetch(u).then((r) => r.text()).catch(() => "");
      let i = -1;
      while ((i = txt.indexOf("default_source_code", i + 1)) !== -1 && out.length < 40) {
        out.push(u.split("/").pop().slice(0, 28) + " :: " + txt.slice(Math.max(0, i - 450), i + 120).replace(/\s+/g, " "));
      }
    }
    return out;
  });
  for (const h of hits) console.log("-", h, "\n");
} catch (e) { console.log("ERROR", e.message.split("\n")[0]); }
finally {
  await fetch(`https://api.browser.tinyfish.ai/${s.session_id}`, { method: "DELETE", headers: { "X-API-Key": key } });
}
EOF
