:root {
  --bg: #f6f7f5;
  --card: #ffffff;
  --text: #1d2320;
  --muted: #66706a;
  --border: #d9ded9;
  --accent: #1f7a4d;
  --accent-text: #ffffff;
  --error: #b42318;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--text);
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #121513;
    --card: #1b1f1c;
    --text: #e7ebe8;
    --muted: #9aa49e;
    --border: #2e3530;
    --accent: #3fb37a;
    --accent-text: #0c120e;
    --error: #ff8a80;
  }
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); }
.page { max-width: 760px; margin: 0 auto; padding: 24px 16px 48px; }
.topbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.topbar h1 { margin: 0; font-size: 1.6rem; }
.who { display: flex; align-items: center; gap: 10px; color: var(--muted); }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 20px; margin: 20px 0; }
.card h2 { margin-top: 0; font-size: 1.2rem; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 0 16px; }
.field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 14px; }
.field span { font-weight: 600; font-size: 0.9rem; }
.field small { color: var(--muted); }
input, select, textarea {
  font: inherit; color: var(--text); background: var(--bg);
  border: 1px solid var(--border); border-radius: 8px; padding: 8px 10px;
}
button {
  font: inherit; font-weight: 600; cursor: pointer; border-radius: 8px; padding: 8px 16px;
  border: 1px solid var(--accent); background: var(--accent); color: var(--accent-text);
}
button.secondary { background: transparent; color: var(--accent); }
button:disabled { opacity: 0.6; cursor: default; }
.actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.muted { color: var(--muted); font-size: 0.85rem; }
.ok { color: var(--accent); }
.error, .field small.error { color: var(--error); }

/* Profile card collapses once saved */
.card details > summary { cursor: pointer; list-style: none; }
.card details > summary::-webkit-details-marker { display: none; }
.card details > summary h2 { display: inline-block; margin-bottom: 12px; }
.card details > summary h2::after { content: " ▾"; color: var(--muted); font-size: 0.9rem; }
.card details:not([open]) > summary h2 { margin-bottom: 0; }
.card details:not([open]) > summary h2::after { content: " ▸"; }

/* Plan result */
.plan h3 { margin: 20px 0 8px; font-size: 1.05rem; }
.plan h4 { margin: 12px 0 4px; font-size: 0.85rem; text-transform: capitalize; color: var(--muted); }
.shopping { list-style: none; padding: 0; margin: 0; }
.shopping li { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid var(--border); text-transform: capitalize; }
.shopping .qty { color: var(--muted); white-space: nowrap; text-transform: none; }
.warnings { padding-left: 18px; margin: 8px 0; }
.warnings li { margin: 4px 0; }
.warn-allergy, .warn-diet, .warn-avoid, .warn-budget { color: var(--error); }
.warn-allergy-check, .warn-long-list { color: var(--muted); }
.plan details { margin-top: 16px; }
.plan details > summary { cursor: pointer; font-weight: 600; }
.day ul { margin: 0; padding-left: 18px; }
.day li { margin: 2px 0; }

/* Shopping list collapses once prices are in */
.shopping-details > summary { cursor: pointer; list-style: none; }
.shopping-details > summary::-webkit-details-marker { display: none; }
.shopping-details > summary h3::after { content: " ▾"; color: var(--muted); font-size: 0.85rem; }
.shopping-details:not([open]) > summary h3::after { content: " ▸"; }

/* T&T prices */
.price-cta { margin: 16px 0 8px; }
.spinner {
  display: inline-block; width: 12px; height: 12px; margin-right: 6px; vertical-align: -1px;
  border: 2px solid var(--border); border-top-color: var(--accent); border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner { animation: none; } }
.prices { margin-top: 12px; }
.prices.stale { opacity: 0.55; }
.total-row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.budget-bar { height: 8px; background: var(--border); border-radius: 4px; overflow: hidden; margin: 8px 0 12px; }
.budget-bar span { display: block; height: 100%; background: var(--accent); }
.budget-bar.over span { background: var(--error); }
.price-list { list-style: none; padding: 0; margin: 0; }
.price-item { border-top: 1px solid var(--border); padding: 12px 0; }
.price-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-bottom: 6px; }
.item-name { font-weight: 600; text-transform: capitalize; }
.chip { font-size: 0.75rem; font-weight: 600; padding: 2px 8px; border-radius: 999px; border: 1px solid currentColor; white-space: nowrap; }
.chip-ok { color: var(--accent); }
.chip-warn { color: #b26b00; }
.chip-bad { color: var(--error); }
@media (prefers-color-scheme: dark) { .chip-warn { color: #f0b45a; } }
.price-body { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.product { display: flex; gap: 10px; align-items: center; min-width: 0; }
.product img, .img-placeholder { width: 44px; height: 44px; object-fit: contain; border-radius: 6px; background: #fff; border: 1px solid var(--border); flex: none; }
.product-name { overflow-wrap: anywhere; }
.product-name a { color: var(--text); }
.line-cost { display: flex; flex-direction: column; align-items: flex-end; flex: none; }
.badge-sale { margin-left: 6px; color: var(--error); font-weight: 600; }
.flags { margin: 6px 0 0; padding-left: 18px; color: var(--muted); font-size: 0.82rem; }
.alts { margin-top: 6px; }
.alts > summary { cursor: pointer; color: var(--muted); font-size: 0.85rem; }
.alt { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 6px 0 0 12px; }
.small { font-size: 0.8rem; margin-top: 12px; }
.warn-not-found, .warn-fetch { color: var(--error); }
.warn-uncertain { color: var(--muted); }

/* Review screen */
.price-item.removed .item-name { text-decoration: line-through; color: var(--muted); }
.chip-muted { color: var(--muted); }
.row-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 14px; margin-top: 8px; }
.stepper { display: inline-flex; align-items: center; gap: 8px; }
.stepper button { padding: 2px 10px; min-width: 32px; }
.link-btn { background: none; border: none; padding: 4px 0; color: var(--accent); font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }
.link-btn:disabled { color: var(--muted); text-decoration: none; }
.options { border: 1px solid var(--border); border-radius: 8px; margin: 8px 0 0; padding: 4px 8px; }
.option { display: flex; align-items: center; gap: 10px; padding: 6px 0; cursor: pointer; }
.option + .option { border-top: 1px solid var(--border); }
.option .product { flex: 1; }
.option.selected .product-name { font-weight: 600; }
.nowrap { white-space: nowrap; }
.search-again { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 8px; }
.search-again input { flex: 1 1 180px; min-width: 0; }
.total-bar {
  position: sticky; bottom: 0; background: var(--card); border-top: 1px solid var(--border);
  padding: 10px 0 4px; margin-top: 8px; z-index: 1;
}
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@media (max-width: 480px) {
  .price-body, .alt { flex-direction: column; align-items: flex-start; }
  .line-cost { align-items: flex-start; }
  .option { align-items: flex-start; }
  .option .nowrap { white-space: normal; }
}

/* Approve & build cart */
.approve { border: 2px solid var(--accent); border-radius: 12px; padding: 16px; margin-top: 20px; }
.approve h3 { margin-top: 0; }
.agree { display: flex; gap: 10px; align-items: flex-start; margin: 12px 0; cursor: pointer; }
.agree input { margin-top: 4px; width: 18px; height: 18px; flex: none; }
.cart-build { border: 1px solid var(--border); border-radius: 12px; padding: 16px; margin: 16px 0; }
.cart-build h3 { margin-top: 0; }
.live-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 12px; margin-bottom: 12px; }
.live-frame { display: flex; flex-direction: column; gap: 4px; }
.live-frame iframe, .live-placeholder {
  width: 100%; aspect-ratio: 16 / 9; border: 1px solid var(--border); border-radius: 8px; background: var(--bg);
}
.live-placeholder { display: flex; align-items: center; justify-content: center; gap: 6px; color: var(--muted); font-size: 0.9rem; padding: 8px; text-align: center; }
.outcomes { list-style: none; padding: 0; margin: 0; }
.outcomes li { border-top: 1px solid var(--border); padding: 8px 0; }
.outcome-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.outcome-head .item-name { text-transform: capitalize; }
.outcome-head .chip .spinner { width: 9px; height: 9px; margin-right: 4px; }
.build-done { margin-top: 12px; }
a.button {
  display: inline-block; font-weight: 600; border-radius: 8px; padding: 8px 16px; text-decoration: none;
  background: var(--accent); color: var(--accent-text); border: 1px solid var(--accent);
}
.build-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.build-head h3 { margin: 0; }
button.danger { color: var(--error); border-color: var(--error); }
.agent-action { font-size: 0.85rem; color: var(--text); background: var(--bg); border-left: 3px solid var(--accent); padding: 4px 8px; border-radius: 4px; overflow-wrap: anywhere; }
.warn-store-stock { color: var(--text); }

